import ast,json,subprocess
from pathlib import Path
paths=subprocess.check_output(['rg','--files','--glob','*.py'],text=True).splitlines(); violations=[]
for name in paths:
 tree=ast.parse(Path(name).read_text(),filename=name)
 for node in ast.walk(tree):
  modules=[]
  if isinstance(node,ast.Import): modules=[x.name for x in node.names]
  if isinstance(node,ast.ImportFrom):
   modules=[node.module or '']
   if node.module=='torx': modules += ['torx.'+x.name for x in node.names if x.name.startswith('_')]
  if isinstance(node,ast.Call) and node.args and isinstance(node.args[0],ast.Constant) and isinstance(node.args[0].value,str):
   if (isinstance(node.func,ast.Name) and node.func.id=='__import__') or (isinstance(node.func,ast.Attribute) and node.func.attr=='import_module'): modules.append(node.args[0].value)
  for module in modules:
   if module.startswith('torx.') and any(x.startswith('_') for x in module.split('.')[1:]): violations.append({'file':name,'line':node.lineno,'module':module})
print(json.dumps({'python_files_scanned':len(paths),'private_torx_imports':violations},indent=2)); assert not violations
